	options := map[string]optionWithValue{}
	for _, entry := range config.ContextOptions {
		options[entry.Name] = optionWithValue{
			ContextOption: entry,
			Value:         entryOptions[entry.Name].Value,
		}
	}

	out, err := json.MarshalIndent(options, "", "  ")
	if err != nil {
		return err
	}
