// getExitAfterTimeout resolves the per-forward idle-shutdown duration.
// Returns 0 (no idle shutdown) when disableIdleTimeout is set or when
// EXIT_AFTER_TIMEOUT is not true in the active context.
func getExitAfterTimeout(devsyConfig *config.Config, disableIdleTimeout bool) time.Duration {
	if disableIdleTimeout {
		return 0
	}
	if devsyConfig.ContextOption(config.ContextOptionExitAfterTimeout) != config.BoolTrue {
		return 0
	}
	return defaultExitTimeout
}

// createForwarder creates a port forwarder if port forwarding is enabled.
func createForwarder(
	opts RunServicesOptions,
	forwardedPorts []string,
	resolver PortAttributeResolver,
) netstat.Forwarder {
	if !opts.ForwardPorts {
		return nil
	}
	ports := append([]string{}, forwardedPorts...)
	ports = append(ports, fmt.Sprintf("%d", openvscode.DefaultVSCodePort))
	ports = append(ports, fmt.Sprintf("%d", codeserver.DefaultCodeServerPort))
	return newForwarder(opts.ContainerClient, ports, resolver)
}

// tunnelServerParams contains parameters for running the tunnel server.
